import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  useMap
} from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";
import { Tooltip } from "react-leaflet";

// ✅ Fix marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

// 🗺️ Fit full path once
function FitBounds({ path }) {
  const map = useMap();

  useEffect(() => {
    if (path.length > 1) {
      map.fitBounds(path, { padding: [50, 50] });
    }
  }, [path, map]);

  return null;
}

function App() {
  const [fullPath, setFullPath] = useState([]);
  const [path, setPath] = useState([]);
  const [latest, setLatest] = useState(null);
  const [isReplayDone, setIsReplayDone] = useState(false);

  // 🚀 Load initial path
  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path");

      const coords = res.data.map(d => [
        d.location.coordinates[1],
        d.location.coordinates[0],
      ]);

      setFullPath(coords);
    } catch (err) {
      console.error(err);
    }
  };

  // 🎬 Replay animation
  useEffect(() => {
    if (fullPath.length === 0) return;

    let index = 0;

    const interval = setInterval(() => {
      if (index >= fullPath.length) {
        clearInterval(interval);
        setIsReplayDone(true);
        return;
      }

      setPath(fullPath.slice(0, index + 1));
      index++;
    }, 200);

    return () => clearInterval(interval);
  }, [fullPath]);

  // 🚁 Live tracking after replay
  useEffect(() => {
    if (!isReplayDone) return;

    const interval = setInterval(fetchLiveData, 3000);
    return () => clearInterval(interval);
  }, [isReplayDone]);

  const fetchLiveData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/latest");

      if (res.data?.location) {
        const newPoint = [
          res.data.location.coordinates[1],
          res.data.location.coordinates[0],
        ];

        setPath(prev => [...prev, newPoint]);
        setLatest(res.data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="dashboard">
      <h2>🚁 Drone Replay + Live Tracking</h2>

      {/* 📊 Telemetry */}
      {latest && (
        <div className="metrics">
          <p>Altitude: {latest.alt}</p>
          <p>Voltage: {latest.voltage}</p>
          <p>Satellites: {latest.sats}</p>
          <p>GPS: {latest.gps_fix}</p>
        </div>
      )}

      <MapContainer center={[12.9716, 77.5946]} zoom={18}>
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* 🔵 Path */}
        <Polyline positions={path} color="blue" />

        {/* 📍 Drone */}
        {path.length > 0 && (
          <Marker position={path[path.length - 1]} />
        )}

        {/* 🗺️ Fit map */}
        <FitBounds path={fullPath} />
      </MapContainer>
    </div>
  );
}

export default App;
